#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Issue #7: end-to-end smoke test of Addon → SavedVariables → Brain → Recommendations.lua
# → Addon prune, in the beta client. Run from anywhere inside the repo, in Git Bash:
#   bash <path>/smoke-test.sh

TOTAL_STAGES=9

REPO=$(git rev-parse --show-toplevel)
BETA_DEFAULT='Z:\Battle.net\World of Warcraft\_classic_beta_'
CONFIG="$REPO/brain/config.toml"
DB="$REPO/brain/history.sqlite"
PY="$REPO/.venv/Scripts/python.exe"
BRAIN="$REPO/.venv/Scripts/brain.exe"
WATCH_LOG=$(mktemp -t aq-watch.XXXXXX.log)
WATCH_PID=""
RESULTS=()   # "PASS  item" / "FAIL  item" lines for the report
SCAN1_AT=""
MARKET_ID=""
SV_SIZE_BEFORE=""

# record PASS|FAIL "checklist item"
record() {
  RESULTS+=("$1  $2")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else printf '  %s✗ %s%s\n' "$RED" "$2" "$RESET"; fi
}

stop_watcher() {
  if [[ -n "$WATCH_PID" ]] && kill -0 "$WATCH_PID" 2>/dev/null; then
    kill "$WATCH_PID" 2>/dev/null || true
  fi
}
trap stop_watcher EXIT

# win PATH: Windows form of a POSIX path, for native python / powershell.
win() { cygpath -w "$1"; }

# sql "SELECT ...": rows tab-separated, via the venv's Python (no sqlite3 CLI needed).
SQL_PY='import sqlite3, sys
c = sqlite3.connect(sys.argv[1])
for r in c.execute(sys.argv[2]):
    print("\t".join(str(v) for v in r))'
sql() { "$PY" -c "$SQL_PY" "$(win "$DB")" "$1" | tr -d '\r'; }

# install_dir: the first [[installs]] path in config.toml, as a POSIX path.
install_dir() {
  local p
  p=$(grep -m1 -E "^path *= *'" "$CONFIG" | sed -E "s/^path *= *'(.*)'.*/\1/")
  cygpath -u "$p"
}

# sv_file: the most recently written AzerothQuant SavedVariables file across accounts.
sv_file() {
  # shellcheck disable=SC2012  # paths have spaces but no newlines
  ls -t "$(install_dir)"/WTF/Account/*/SavedVariables/AzerothQuant.lua 2>/dev/null | head -n1
}

log_lines() { wc -l < "$WATCH_LOG"; }

# wait_for_import FROM_LINE [PATTERN]: block until the watcher logs an import of >=1
# new Scan (or a line matching PATTERN) after line FROM_LINE of its log, echoing what
# it logs meanwhile.
wait_for_import() {
  local from="$1" seen="$1" total
  local pattern="${2:-Imported .*: [1-9][0-9]* new Scans}"
  note "Waiting for the watcher (Ctrl-C to give up)..."
  while :; do
    total=$(log_lines)
    if (( total > seen )); then
      sed -n "$((seen + 1)),${total}p" "$WATCH_LOG" | sed 's/^/    /'
      seen=$total
    fi
    if tail -n +"$((from + 1))" "$WATCH_LOG" | grep -qE "$pattern"; then
      return 0
    fi
    if ! kill -0 "$WATCH_PID" 2>/dev/null; then
      warn "The watcher has stopped; see $WATCH_LOG"
      return 1
    fi
    sleep 1
  done
}

banner "azerothquant: end-to-end smoke test (#7)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Brain config"
if [[ ! -x "$BRAIN" ]]; then
  warn "The Brain isn't installed in .venv. Run this first (PowerShell, repo root):"
  note '  python -m venv .venv; .\.venv\Scripts\python -m pip install -e "brain[dev]"'
  exit 1
fi
if [[ -f "$CONFIG" ]]; then
  say "brain/config.toml already exists; using it as is:"
  grep -vE '^[[:space:]]*(#|$)' "$CONFIG" | sed 's/^/    /'
else
  say "brain/config.toml tells the Brain which WoW folder to read, and that it's Beta data."
  ask BETA_DIR "Beta install folder (Enter for $BETA_DEFAULT):"
  BETA_DIR=${BETA_DIR:-$BETA_DEFAULT}
  if [[ ! -d "$(cygpath -u "$BETA_DIR")" ]]; then warn "No such folder: $BETA_DIR"; exit 1; fi
  if confirm "Write brain/config.toml with that folder as era = \"beta\"?"; then
    printf "# Per-machine; see config.example.toml.\n\n[[installs]]\npath = '%s'\nera = \"beta\"\n" \
      "$BETA_DIR" > "$CONFIG"
    printf '  %s✓ wrote%s brain/config.toml\n' "$GREEN" "$RESET"
  else
    warn "Can't continue without a config."
    exit 1
  fi
fi
pause "Continue?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Install the Addon into the beta client"
ADDON_LINK="$(install_dir)/Interface/AddOns/AzerothQuant"
if [[ -e "$ADDON_LINK" ]]; then
  say "Interface\\AddOns\\AzerothQuant already exists; leaving it alone."
  note "(If it's an old copy rather than a link to the repo, delete it and re-run.)"
else
  say "A directory junction makes the game load the Addon straight from the repo, so"
  say "code changes show up on /reload, and the Brain's Recommendations.lua lands in"
  say "addon/AzerothQuant/. Junctions don't need admin rights."
  if confirm "Create the junction $(win "$ADDON_LINK") → addon\\AzerothQuant?"; then
    powershell.exe -NoProfile -Command \
      "New-Item -ItemType Junction -Path '$(win "$ADDON_LINK")' -Target '$(win "$REPO/addon/AzerothQuant")' | Out-Null"
    printf '  %s✓ linked%s\n' "$GREEN" "$RESET"
  else
    warn "Copy addon\\AzerothQuant into that AddOns folder yourself, then continue."
  fi
fi
git -C "$REPO" update-index --skip-worktree addon/AzerothQuant/Recommendations.lua
note "Marked addon/AzerothQuant/Recommendations.lua skip-worktree, so the Brain's"
note "rewrites of it don't show up in git status."
pause "Continue?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Start the Brain watcher"
say "Running 'brain watch' in the background until this wizard exits."
( cd "$REPO/brain" && exec "$BRAIN" --config "$(win "$CONFIG")" watch ) >"$WATCH_LOG" 2>&1 &
WATCH_PID=$!
sleep 3
if ! kill -0 "$WATCH_PID" 2>/dev/null; then
  warn "The watcher exited straight away:"
  sed 's/^/    /' "$WATCH_LOG"
  exit 1
fi
sed 's/^/    /' "$WATCH_LOG"
note "Full log: $WATCH_LOG"
pause "Continue?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Addon loads with no Lua errors"
step "Launch the WoW Forever beta from Battle.net. At character select, click AddOns"
step "(bottom left): check AzerothQuant is listed and enabled, and turn off AQProbe."
step "Log in on an Alliance character near an Alliance Auction House."
step "In chat, run  /console scriptErrors 1  and then  /reload"
say  "Watch for a Lua error popup or red error text mentioning AzerothQuant."
ITEM="Addon loads with no Lua errors"
if confirm "Did it load with no Lua errors?"; then
  record PASS "$ITEM"
else
  record FAIL "$ITEM"
  warn "Note the error text for the issue."
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Scan #1 at the Alliance Auction House"
step "Talk to an auctioneer in an Alliance city (not Booty Bay or Gadgetzan: those are Neutral)."
step "Click the 'Scan' button just above the top-right corner of the Auction House window."
step "Keep the AH open. Within a minute, chat should say:"
note "    AzerothQuant Scan #N saved: X Listings, Y dropped for missing item data."
say  "Don't /reload yet."
ITEM="Click Scan at the Alliance AH, wait for the completion message"
if confirm "Did you get the 'Scan #N saved' message?"; then
  record PASS "$ITEM"
else
  record FAIL "$ITEM"
  warn "The rest can't be tested without a Scan."
  exit 1
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "/reload → the watcher imports Scan #1"
ITEM="/reload: watcher imports; DB has a Scan and Listings for the right Market"
# From the top of the log, and "already imported" counts: on a re-run the Scan may be
# on disk (imported at watcher startup) or already in the history from a previous run.
step "In game, type  /reload  (skip it if you already did after this Scan)"
if ! wait_for_import 0 'Imported .*: ([1-9][0-9]* new Scans|[0-9]+ new Scans, [1-9][0-9]* already imported)'; then
  record FAIL "$ITEM"
  exit 1
fi
printf '\n'
say "The history now holds (market id, realm, faction, era, Scans, Listings):"
sql "SELECT m.id, m.realm, m.faction, m.era,
       (SELECT COUNT(*) FROM scan s WHERE s.market_id = m.id),
       (SELECT COUNT(*) FROM listing l WHERE l.market_id = m.id)
     FROM market m ORDER BY m.id" | sed 's/^/    /'
read -r MARKET_ID SCAN1_AT < <(sql "SELECT market_id, requested_at FROM scan ORDER BY id DESC LIMIT 1")
LISTINGS=$(sql "SELECT COUNT(*) FROM listing WHERE market_id = $MARKET_ID")
if (( LISTINGS > 0 )) && confirm "Is market $MARKET_ID your realm, faction Alliance, era beta?"; then
  record PASS "$ITEM"
else
  record FAIL "$ITEM"
fi
SV=$(sv_file)
SV_SIZE_BEFORE=$(stat -c %s "$SV")
note "SavedVariables with the Scan in it: $SV_SIZE_BEFORE bytes ($(win "$SV"))"
pause "Continue?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "/reload again → the Addon prunes the imported Scan"
say "The Brain has rewritten Recommendations.lua. On this load the Addon reads it and"
say "deletes Scan #1 from SavedVariables, which the game then saves."
step "In game, type  /reload"
step "Look for:  AzerothQuant Deleted 1 Scans the Brain has imported ..."
pause "Press Enter once the game has reloaded."
sleep 2
SV_SIZE_AFTER=$(stat -c %s "$(sv_file)")
say "SavedVariables: $SV_SIZE_BEFORE → $SV_SIZE_AFTER bytes"
ITEM="/reload again: Addon pruned the imported Scan from SavedVariables (file size drops)"
# The Scan is nearly all of the file, so pruning it should more than halve it.
if (( SV_SIZE_AFTER < SV_SIZE_BEFORE / 2 )); then
  record PASS "$ITEM"
else
  record FAIL "$ITEM"
fi
pause "Continue?"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Scan #2 after the cooldown, then log out"
say "The AH silently ignores a re-scan within ~15 min of the last one, so wait that out."
while :; do
  left=$(( SCAN1_AT + 15 * 60 + 30 - $(date +%s) ))
  (( left <= 0 )) && break
  printf '\r  %sScan unlocks in %d:%02d (you can stay in game)%s  ' \
    "$DIM" $((left / 60)) $((left % 60)) "$RESET"
  sleep 1
done
printf '\r  %s✓ cooldown over%s                                        \n' "$GREEN" "$RESET"
step "Open the same Alliance AH and click Scan. Wait for 'Scan #N saved'."
step "Then LOG OUT (Esc → Log Out, back to character select). Don't /reload."
FROM=$(log_lines)
ITEM_LOGOUT="Log out instead of /reload: import still happens"
ITEM_MATCH="Scan again 15+ min later: some Listings extend, some show as Disappearances"
if wait_for_import "$FROM"; then
  record PASS "$ITEM_LOGOUT"
  read -r LATEST PREV < <(sql "SELECT
      (SELECT id FROM scan WHERE market_id = $MARKET_ID ORDER BY requested_at DESC LIMIT 1),
      (SELECT id FROM scan WHERE market_id = $MARKET_ID ORDER BY requested_at DESC LIMIT 1 OFFSET 1)")
  read -r EXTENDED GONE NEW PARTIAL < <(sql "SELECT
      (SELECT COUNT(*) FROM listing WHERE first_seen_scan_id = $PREV AND last_seen_scan_id = $LATEST),
      (SELECT COUNT(*) FROM listing WHERE market_id = $MARKET_ID AND last_seen_scan_id = $PREV),
      (SELECT COUNT(*) FROM listing WHERE first_seen_scan_id = $LATEST),
      (SELECT COUNT(*) FROM partial_sale WHERE scan_id = $LATEST)")
  printf '\n'
  say "Between Scan #1 and Scan #2:"
  note "    extended (in both):  $EXTENDED"
  note "    Disappearances:      $GONE"
  note "    new Listings:        $NEW"
  note "    Partial Sales:       $PARTIAL"
  if (( EXTENDED > 0 && GONE > 0 )); then
    record PASS "$ITEM_MATCH"
  else
    record FAIL "$ITEM_MATCH"
  fi
else
  record FAIL "$ITEM_LOGOUT"
fi
pause "Continue?"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Report"
REPORT=$(mktemp -t aq-report.XXXXXX.md)
{
  echo "Smoke test run $(date '+%Y-%m-%d %H:%M') with the wizard."
  echo
  for r in "${RESULTS[@]}"; do
    if [[ "$r" == PASS* ]]; then echo "- [x] ${r#PASS  }"; else echo "- [ ] **FAILED:** ${r#FAIL  }"; fi
  done
  echo
  echo "Scan #2 vs #1: ${EXTENDED:-?} extended, ${GONE:-?} Disappearances, ${NEW:-?} new, ${PARTIAL:-?} Partial Sales."
} > "$REPORT"
sed 's/^/    /' "$REPORT"
printf '\n'
if confirm "Post this as a comment on issue #7?"; then
  if gh issue comment 7 --repo zachmanson/azerothquant --body-file "$(win "$REPORT")" >/dev/null; then
    printf '  %s✓ posted to #7%s\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("comment on #7 (report saved at $REPORT)")
  fi
else
  SKIPPED+=("comment on #7 if you want (report saved at $REPORT)")
fi
stop_watcher
note "Stopped the watcher. Its log: $WATCH_LOG"
pause "Finish?"
# ──────────────────────────────────────────────────────────────────────────

finish
